        "MSFT",
        "GOOGL",
        "META",
        "AMZN",
        "NVDA",
        "AMD"
      ],
      "claim_period": "Interviews October 1–8, 2026; received October 12",
      "citation": {
        "source_id": "channel-oct2026",
        "quote": "Sample: 8 respondents — 3 ODM/OEM supply managers, 2 power and cooling vendors, 2 neocloud procurement leads, 1 hyperscaler data center planner."
      }
    },
    {
      "statement": "Three ODM/OEM respondents reportedly described larger 2027 cloud rack orders; no order value or customer-specific budget was disclosed.",
      "entities": [
        "MSFT",
        "GOOGL",
        "META",
        "AMZN"
      ],
      "claim_period": "2027 order indications as of October 1–8, 2026",
      "citation": {
        "source_id": "channel-oct2026",
        "quote": "All three ODM/OEM respondents described 2027 rack orders from the largest US clouds as \"larger than 2026\", with the mix shifting toward rack-scale systems."
      }
    },
    {
      "statement": "Two respondents reportedly saw rising custom-accelerator share of new rack orders at two unnamed Big Four clouds; the check does not quantify dollar share.",
      "entities": [
        "MSFT",
        "GOOGL",
        "META",
        "AMZN",
        "NVDA"
      ],
      "claim_period": "Forward orders discussed October 1–8, 2026; delivery-year detail unspecified",
      "citation": {
