      "entities": [
        "MSFT",
        "GOOGL",
        "META",
        "AMZN"
      ],
      "claim_period": "2027 deployment planning",
      "citation": {
        "source_id": "channel-oct2026",
        "quote": "The hyperscaler planner said 2027 power availability, not chip supply, sets the deployment pace at their company."
      }
    },
    {
      "statement": "Neocloud procurement leads reportedly described stable NVIDIA lead times of roughly 20–30 weeks and improving AMD system availability.",
      "entities": [
        "NVDA",
        "AMD"
      ],
      "claim_period": "October 1–8, 2026 procurement observations",
      "citation": {
