      "entities": [
        "AMZN"
      ],
      "claim_period": "Commitment disclosed April 29, 2026; ramp begins 2027",
      "citation": {
        "source_id": "amzn-2026-04-29-release",
        "quote": "Secured a commitment from OpenAI to consume approximately two gigawatts (GW) of Trainium capacity through AWS infrastructure to power its frontier models and advanced workloads, which begins ramping in 2027."
      }
